function [total, img] = smear(img, at, w)
%SMEAR  Arrays by reference: an inout input is changed in place, the caller's variable with it (no copy in a translation).
%   img: inout real[1][8] (passed a plain number)
%   at: int (passed a whole number)
%   w: real[1] (passed a plain number)
%   returns total: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    total = 0;
    img((at) + 1) = (img((at) + 1) + w);
    if (at > 0)
        img(((at - 1)) + 1) = (img(((at - 1)) + 1) + (w / 2));
    end
    total = 0;
    for i = (0):((8) - 1)
        total = (total + img((i) + 1));
    end
end
